// accessRequestUsage displays the usage of the access-request command and its
// subcommands.
func accessRequestUsage() {
	fmt.Fprintf(os.Stderr, `Access request management service for ABAC authorization
Usage:
    %[1]s [globalflags] access-request COMMAND [flags]

COMMAND:
    create: Create a new access request
    get: Get access request by ID
    process: Process an access request (approve/deny)
    revoke: Revoke an access request
    list: List access requests with filtering
    stats: Get access request statistics
    evaluate-conditional-access: Evaluate conditional access rules
    create-conditional-rule: Create a conditional access rule
    user-behavior-analytics: Get user behavior analytics
    user-risk-assessment: Get user risk assessment
    user-insights: Get personalized user insights
    detect-anomalies: Detect user behavior anomalies

Additional help:
    %[1]s access-request COMMAND --help
`, os.Args[0])
}
func accessRequestCreateUsage() {
	fmt.Fprintf(os.Stderr, `%[1]s [flags] access-request create -body JSON

Create a new access request
    -body JSON: 

Example:
    %[1]s access-request create --body '{
      "access_level": "read",
      "duration_hours": 24,
      "entity_id": "123e4567-e89b-12d3-a456-426614174000",
      "metadata": {
         "Aperiam ab ullam accusamus.": "Rerum atque voluptas.",
         "Est maiores non ratione rerum iure.": "Consequatur totam.",
         "Id totam est non nesciunt.": "Omnis numquam id impedit."
      },
      "reason": "Need access to review quarterly reports",
      "requester_id": "123e4567-e89b-12d3-a456-426614174000",
      "resource_type": "document"
   }'
`, os.Args[0])
}

